/bin/bash -lc "python3 - <<'PY'
import json,urllib.request,math
ids={'RUNX1':'MA0002.3','TFAP2A_MA0003':'MA0003.5','GATA3':'MA0037.5','KLF4':'MA0039.5','SPI1':'MA0080.7','REST':'MA0138.3','FOXA1':'MA0148.5','PAX7':'MA0680.3','TCF7':'MA0769.3','TFAP2A_MA0810':'MA0810.2','TFAP2A_MA0872':'MA0872.1','ASCL1_MA1100':'MA1100.3','ASCL1_MA1631':'MA1631.2'}
# observed counts all gained and control
obs_g={'RUNX1':10752,'TFAP2A_MA0003':11305,'GATA3':3844,'KLF4':37205,'SPI1':19286,'REST':7436,'FOXA1':4173,'PAX7':5593,'TCF7':5400,'TFAP2A_MA0810':9358,'TFAP2A_MA0872':8531,'ASCL1_MA1100':11152,'ASCL1_MA1631':10621}
obs_c={'RUNX1':22687,'TFAP2A_MA0003':61948,'GATA3':4733,'KLF4':50406,'SPI1':46118,'REST':37092,'FOXA1':7847,'PAX7':3785,'TCF7':5398,'TFAP2A_MA0810':97904,'TFAP2A_MA0872':82445,'ASCL1_MA1100':45523,'ASCL1_MA1631':43009}
freq_g={'A':8124842/27455385,'C':5585166/27455385,'G':5584761/27455385,'T':8160616/27455385}
freq_c={'A':11777745/52016265,'C':14207008/52016265,'G':14221984/52016265,'T':11809528/52016265}
bp_g=27455385; bp_c=52016265
rows=[]
for name,mid in ids.items():
    data=json.load(urllib.request.urlopen(f'https://jaspar.elixir.no/api/v1/matrix/{mid}/'))
    pfm=data['pfm']; order=['A','C','G','T']
    pg=1; pc=1
    for i in range(len(pfm['A'])):
        vals=[pfm[b][i] for b in order]; total=sum(vals); probs=[v/total for v in vals]
        pg*=sum(probs[j]*freq_g[order[j]] for j in range(4))
        pc*=sum(probs[j]*freq_c[order[j]] for j in range(4))
    exp_g=bp_g*pg; exp_c=bp_c*pc
    enrich=(obs_g[name]/exp_g)/(obs_c[name]/exp_c)
    rows.append((name,obs_g[name],exp_g,obs_c[name],exp_c,enrich,math.log2(enrich)))
for r in sorted(rows,key=lambda x:x[5],reverse=True):
    print(f'{r[0]:20s} obsG={r[1]:6d} expG={r[2]:8.1f} obsC={r[3]:6d} expC={r[4]:8.1f} enrich={r[5]:.3f} log2={r[6]:+.2f}')
PY"
